import React from 'react';
import { Link } from 'react-router-dom';
// Import the necessary icons
import { FaPhoneAlt, FaFacebookF, FaInstagram, FaLinkedinIn } from 'react-icons/fa';

const styles = {
  // Container for the entire footer area, including the "Call Us" card
  footerWrapper: {
    backgroundColor: '#1a202c', // Dark blue background
    color: '#a0aec0',
    padding: '50px 30px',
    fontFamily: 'sans-serif',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
  },
  // --- New "Call Us" Card Styles ---
  contactCard: {
    backgroundColor: '#2d3748', // Slightly lighter dark blue
    borderRadius: '15px',
    padding: '20px 30px',
    maxWidth: '500px',
    margin: '0 auto 50px auto', // Center the card and add space below
    display: 'flex',
    alignItems: 'center',
    gap: '20px',
  },
  contactIcon: {
    color: '#63e6be', // Mint green icon color
    fontSize: '24px',
  },
  contactTextContainer: {
    textAlign: 'left',
  },
  contactTitle: {
    color: '#ffffff',
    margin: '0 0 5px 0',
    fontSize: '1.1rem',
    fontWeight: 'bold',
  },
  contactDetails: {
    margin: 0,
    fontSize: '1rem',
  },
  // --- Main Footer Content Styles ---
  mainContent: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    flexWrap: 'wrap',
    gap: '30px',
  },
  branding: {
    textAlign: 'left',
  },
  clinicName: {
    color: '#ffffff',
    fontSize: '2rem',
    fontWeight: 'bold',
    margin: '0 0 8px 0',
  },
  tagline: {
    color: '#a0aec0',
    fontSize: '1rem',
    margin: 0,
    fontStyle: 'italic',
  },
  socialsContainer: {
    marginTop: '20px',
    display: 'flex',
    gap: '15px',
  },
  nav: {
    display: 'flex',
    gap: '25px',
    flexWrap: 'wrap',
    marginTop: '10px',
  },
  // --- Footer Bottom (Line and Copyright) ---
  footerBottom: {
    textAlign: 'center',
    paddingTop: '30px',
    marginTop: '30px',
    borderTop: '1px solid #2d3748', // The subtle horizontal line
    fontSize: '0.9rem',
    color: '#a0aec0',
  }
};

// CSS for dynamic link and icon hover effects
const dynamicStyles = `
  .footer-nav-link {
    color: #a0aec0;
    text-decoration: none;
    font-size: 1rem;
    transition: color 0.3s ease;
  }

  .footer-nav-link:hover {
    color: #ffffff;
  }

  /* Updated social icon styles to match the image */
  .social-icon {
    background-color: #4a5568; /* Gray background */
    color: #e2e8f0; /* Light icon color */
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    text-decoration: none;
    transition: background-color 0.3s ease, transform 0.3s ease;
  }

  .social-icon:hover {
    background-color: #718096; /* Lighter gray on hover */
    transform: translateY(-3px);
  }
`;

const Footer = () => {
  const footerLinks = [
    { text: 'Home', path: '/', isRouterLink: true },
    { text: 'About Us', path: '/about', isRouterLink: true },
    { text: 'Services', path: '/#services', isRouterLink: false },
    { text: 'Contact Us', path: '/#contact', isRouterLink: false },
    { text: 'Terms and Conditions', path: '/terms', isRouterLink: true },
  ];

  return (
    <>
      <style>{dynamicStyles}</style>

      <div style={styles.footerWrapper}>
        <div style={styles.container}>
          {/* --- "Call Us" Section --- */}
          <div style={styles.contactCard}>
            <div style={styles.contactIcon}>
              <FaPhoneAlt />
            </div>
            <div style={styles.contactTextContainer}>
              <h3 style={styles.contactTitle}>Call Us</h3>
              <p style={styles.contactDetails}>+91 90031 49989 (9AM - 7PM IST)</p>
            </div>
          </div>

          {/* --- Main Footer Section --- */}
          <footer >
            <div style={styles.mainContent}>
              {/* Left Column: Branding and Socials */}
              <div style={styles.branding}>
                <h2 style={styles.clinicName}>Karpagam Clinic</h2>
                <p style={styles.tagline}>Your Health, Our Priority</p>
                <div style={styles.socialsContainer}>
                  <a href="https://facebook.com" className="social-icon" target="_blank" rel="noopener noreferrer" aria-label="Facebook"><FaFacebookF /></a>
                  <a href="https://instagram.com" className="social-icon" target="_blank" rel="noopener noreferrer" aria-label="Instagram"><FaInstagram /></a>
                  <a href="https://linkedin.com" className="social-icon" target="_blank" rel="noopener noreferrer" aria-label="LinkedIn"><FaLinkedinIn /></a>
                </div>
              </div>

              {/* Right Column: Navigation */}
              <nav style={styles.nav}>
                {footerLinks.map(({ text, path, isRouterLink }) => 
                  isRouterLink ? (
                    <Link key={text} to={path} className="footer-nav-link">{text}</Link>
                  ) : (
                    <a key={text} href={path} className="footer-nav-link">{text}</a>
                  )
                )}
              </nav>
            </div>

            {/* --- Bottom Section: Line and Copyright --- */}
            <div style={styles.footerBottom}>
              © {new Date().getFullYear()} Karpagam Clinic. All Rights Reserved.
            </div>
          </footer>
        </div>
      </div>
    </>
  );
};

export default Footer;
